18	// fixtureChain builds: publish v1 with one allow policy (seq 1), an allowed
19	// decision (seq 2), publish v2 with no policies (seq 3), a default-deny
20	// decision (seq 4). It archives the full export and returns the file path
21	// and the separately retained checkpoint.
22	func fixtureChain(t *testing.T, org string) (string, darksafe.Checkpoint) {
23		t.Helper()
24		s := darksafe.NewStore()
25		s.Publish(org, 0, []darksafe.Policy{
26			{ID: "p1 ledger", Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
27		})
28		s.Decide(org, darksafe.OrgRequest{
29			SubjectOrg: org, ResourceOrg: org,
30			Subject:  darksafe.Subject{ID: "u1"},
31			Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
32			Action:   "read",
33		})
34		if v, err := s.Publish(org, 1, nil); err != nil || v != 2 {
35			t.Fatalf("publish v2: %d %v", v, err)
36		}
37		s.Decide(org, darksafe.OrgRequest{
38			SubjectOrg: org, ResourceOrg: org,
39			Subject:  darksafe.Subject{ID: "u1"},
40			Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
41			Action:   "read",
42		})
43		recs, cp, err := s.AuditExport(org, 0)
44		if err != nil {
45			t.Fatal(err)
46		}
47		archive, err := darksafe.EncodeAuditArchive(org, recs, cp)
48		if err != nil {
49			t.Fatal(err)
50		}
51		path := filepath.Join(t.TempDir(), "audit.bin")
52		if err := os.WriteFile(path, archive, 0o600); err != nil {
53			t.Fatal(err)
54		}
55		return path, cp
56	}
57	
58	// runDispatch invokes the full top-level dispatch and captures everything.
59	func runDispatch(t *testing.T, args ...string) (int, string, string) {
60		t.Helper()
61		var stdout, stderr bytes.Buffer
62		code := dispatch(append([]string{"darksafe"}, args...), &stdout, &stderr)
63		return code, stdout.String(), stderr.String()
64	}
65	
66	func reviewArgs(path, org string, seq, endSeq int, fp string) []string {
67		return []string{
68			"review",
69			"--archive", path,
70			"--org", org,
71			"--seq", strconv.Itoa(seq),
72			"--end-seq", strconv.Itoa(endSeq),
73			"--fingerprint", fp,
74		}
75	}
76	
77	// TestReviewSuccessPrintsBothDecisions verifies the happy path: both the
78	// original and recomputed decisions are shown with allowance, reason,
79	// matched policies and version, plus an explicit consistency verdict.
80	func TestReviewSuccessPrintsBothDecisions(t *testing.T) {
81		const org = "acme payments" // spaces in the organization name
82		path, cp := fixtureChain(t, org)
83	
84		code, out, errOut := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...)
85		if code != 0 {
86			t.Fatalf("exit = %d, stderr = %q", code, errOut)
87		}
88		if errOut != "" {
89			t.Fatalf("unexpected stderr: %q", errOut)
90		}
91		for _, want := range []string{
92			"target sequence: 2",
93			"original decision:",
94			"recomputed decision:",
95			"allowed: true",
96			`reason: "matched allow policy"`,
97			`matched policies: ["p1 ledger"]`,
98			"policy version: 1",
99			"consistent: yes",
100		} {
101			if !strings.Contains(out, want) {
102				t.Fatalf("output missing %q:\n%s", want, out)
103			}
104		}
105	}
106	
107	// TestReviewUsesRecordedVersionNotNewer proves a later publish cannot change
108	// the recomputed decision: seq 2 used v1 even though v2 (no policies) is the
109	// current version at export time; seq 4 used v2 and denies by default.
110	func TestReviewUsesRecordedVersionNotNewer(t *testing.T) {
111		const org = "acme"
112		path, cp := fixtureChain(t, org)
113	
114		code, early, _ := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...)
115		if code != 0 {
116			t.Fatalf("seq 2 exit = %d", code)
117		}
118		if !strings.Contains(early, "allowed: true") || !strings.Contains(early, "policy version: 1") {
119			t.Fatalf("early decision must replay v1 allow:\n%s", early)
120		}
121	
122		code, late, _ := runDispatch(t, reviewArgs(path, org, 4, cp.EndSeq, cp.Fingerprint)...)
123		if code != 0 {
124			t.Fatalf("seq 4 exit = %d", code)
125		}
126		if !strings.Contains(late, "allowed: false") ||
127			!strings.Contains(late, `reason: "no matching allow policy"`) ||
128			!strings.Contains(late, "policy version: 2") {
129			t.Fatalf("late decision must replay v2 default deny:\n%s", late)
130		}
131	}
132	
133	// TestReviewInconsistencyRendersCompletely covers the rendering of a
134	// legitimate-but-inconsistent result: both decisions are printed in full,
135	// the disagreement is explicit, and it is still a successful exit.
136	func TestReviewInconsistencyRendersCompletely(t *testing.T) {
137		var stdout bytes.Buffer
138		printReview(&stdout, darksafe.OfflineDecisionReview{
139			Seq: 7,
140			Original: darksafe.Decision{
141				Allowed: true, Reason: "matched allow policy",
142				Matched: []string{"p1"}, Version: 3,
143			},
144			Recomputed: darksafe.Decision{
145				Allowed: false, Reason: "matched deny policy",
146				Matched: []string{"p1", "p2"}, Version: 3,
147			},
148			Consistent: false,
149		})
150		out := stdout.String()
151		for _, want := range []string{
152			"target sequence: 7",
153			"original decision:",
154			"recomputed decision:",
155			"consistent: no",
156			`reason: "matched allow policy"`,
157			`reason: "matched deny policy"`,
158			`matched policies: ["p1", "p2"]`,
159		} {
160			if !strings.Contains(out, want) {
161				t.Fatalf("inconsistent output missing %q:\n%s", want, out)
162			}
163		}
164	}
165	
166	// TestReviewUsageFailuresExitTwo covers every exit-2 condition: missing
167	// required inputs, unparsable integers, non-positive target, negative end
168	// sequence, unknown/unexpected arguments, and an unreadable archive.
169	func TestReviewUsageFailuresExitTwo(t *testing.T) {
170		const org = "acme"
171		path, cp := fixtureChain(t, org)
172		base := reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)
173	
174		dropFlag := func(name string) []string {
175			out := make([]string, 0, len(base)-2)
176			for i := 0; i < len(base); i++ {
177				if base[i] == name {
178					i++ // also drop its value
179					continue
180				}
181				out = append(out, base[i])
182			}
183			return out
184		}
185	
186		// --flag=value with a non-integer value must fail exactly like the
187		// separated form.
188		eqBad := reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)
189		for i := range eqBad {
190			if eqBad[i] == "--seq" {
191				eqBad[i] = "--seq=nope"
192				eqBad = append(eqBad[:i+1], eqBad[i+2:]...)
193				break
194			}
195		}
196	
197		cases := []struct {
198			name string
199			args []string
200		}{
201			{"no arguments", []string{"review"}},
202			{"missing archive", dropFlag("--archive")},
203			{"missing org", dropFlag("--org")},
204			{"missing seq", dropFlag("--seq")},
205			{"missing end-seq", dropFlag("--end-seq")},
206			{"missing fingerprint", dropFlag("--fingerprint")},
207			{"non-integer seq", replaceArg(base, "--seq", "abc")},
208			{"float seq", replaceArg(base, "--seq", "1.5")},
209			{"non-integer end-seq", replaceArg(base, "--end-seq", "xx")},
210			{"zero seq", replaceArg(base, "--seq", "0")},
211			{"negative seq", replaceArg(base, "--seq", "-4")},
212			{"negative end-seq", replaceArg(base, "--end-seq", "-1")},
213			{"equals form bad int", eqBad},
214			{"unknown flag", append(append([]string{}, base...), "--bogus")},
215			{"positional argument", append(append([]string{}, base...), "leftover")},
216			{"missing file", replaceArg(base, "--archive", filepath.Join(t.TempDir(), "nope.bin"))},
217			{"archive is directory", replaceArg(base, "--archive", t.TempDir())},
218		}
219	
220		for _, tc := range cases {
221			t.Run(tc.name, func(t *testing.T) {
222				code, out, errOut := runDispatch(t, tc.args...)
223				if code != 2 {
224					t.Fatalf("exit = %d, want 2; stdout=%q stderr=%q", code, out, errOut)
225				}
226				if errOut == "" {
227					t.Fatal("expected a specific reason on stderr")
228				}
229				if out != "" {
230					t.Fatalf("usage failure must print nothing to stdout, got %q", out)
231				}
232			})
233		}
234	}
235	
236	func replaceArg(base []string, flag, value string) []string {
237		out := append([]string{}, base...)
238		for i := range out {
239			if out[i] == flag {
240				out[i+1] = value
241				return out
242			}
243		}
244		return out
245	}
246	
247	// TestReviewMaterialAndTargetFailuresExitOne covers the exit-1 family:
248	// unrecognized bytes, checkpoint mismatch (the archive's own checkpoint
249	// cannot substitute), a target past the export, and a non-decision target.
250	// None of them may print partial decision content.
251	func TestReviewMaterialAndTargetFailuresExitOne(t *testing.T) {
252		const org = "acme"
253		path, cp := fixtureChain(t, org)
254		dir := filepath.Dir(path)
255	
256		garbage := filepath.Join(dir, "garbage.bin")
257		if err := os.WriteFile(garbage, []byte("not an archive"), 0o600); err != nil {
258			t.Fatal(err)
259		}
260	
261		// Flip a byte in a valid file: checksum/framing fails and no records are
262		// delivered.
263		good, err := os.ReadFile(path)
264		if err != nil {
265			t.Fatal(err)
266		}
267		corrupt := append([]byte(nil), good...)
268		corrupt[len(corrupt)-40] ^= 0x01
269		corruptPath := filepath.Join(dir, "corrupt.bin")
270		if err := os.WriteFile(corruptPath, corrupt, 0o600); err != nil {
271			t.Fatal(err)
272		}
273	
274		cases := []struct {
275			name string
276			args []string
277		}{
278			{"unrecognized archive", reviewArgs(garbage, org, 2, cp.EndSeq, cp.Fingerprint)},
279			{"corrupted bytes", reviewArgs(corruptPath, org, 2, cp.EndSeq, cp.Fingerprint)},
280			{"wrong fingerprint", reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint[:len(cp.Fingerprint)-1]+"0")},
281			{"foreign organization", reviewArgs(path, "globex", 2, cp.EndSeq, cp.Fingerprint)},
282			{"wrong end sequence", reviewArgs(path, org, 2, cp.EndSeq-1, cp.Fingerprint)},
283			{"target past export", reviewArgs(path, org, 99, cp.EndSeq, cp.Fingerprint)},
284			{"target is policy change", reviewArgs(path, org, 1, cp.EndSeq, cp.Fingerprint)},
285		}
286	
287		for _, tc := range cases {
288			t.Run(tc.name, func(t *testing.T) {
289				code, out, errOut := runDispatch(t, tc.args...)
290				if code != 1 {
291					t.Fatalf("exit = %d, want 1; stderr=%q", code, errOut)
292				}
293				if errOut == "" {
294					t.Fatal("expected a distinguishable failure reason on stderr")
295				}
296				if out != "" {
297					t.Fatalf("failure must not print a partial decision, stdout=%q", out)
298				}
299			})
300		}
301	}
302	
303	// archiveMagicV1 mirrors the darksafe package's stable framing prefix; the
304	// format is explicitly versioned (…-v1), so the CLI test relies only on its
305	// published layout.
306	const archiveMagicV1 = "darksafe-audit-archive-v1\n"
307	
308	// reframeArchive parses one archive frame, lets mutate alter the payload in
309	// place, and rebuilds a frame with a consistent declared length and
310	// checksum, so a test can tamper content without tripping framing/checksum
311	// checks and reach the library's whole-chain validation.
312	func reframeArchive(t *testing.T, data []byte, mutate func(payload []byte)) []byte {
313		t.Helper()
314		magicLen := len(archiveMagicV1)
315		n := int(binary.BigEndian.Uint32(data[magicLen : magicLen+4]))
316		payload := append([]byte(nil), data[magicLen+4:magicLen+4+n]...)
317		mutate(payload)
318		out := append([]byte(nil), archiveMagicV1...)
319		var lb [4]byte
320		binary.BigEndian.PutUint32(lb[:], uint32(len(payload)))
321		out = append(out, lb[:]...)
322		out = append(out, payload...)
323		sum := sha256.Sum256(payload)
324		return append(out, sum[:]...)
325	}
326	
327	// TestReviewValidatesMaterialAfterTarget builds a chain whose early decision
328	// (seq 2) is the review target but whose LATER record (seq 4, a uniquely
329	// named subject) is tampered with a valid checksum. Decode parses it and the
330	// whole-chain check must reject it: even an early target validates every
331	// record, and no partial decision is printed.
332	func TestReviewValidatesMaterialAfterTarget(t *testing.T) {
333		const org = "acme"
334		s := darksafe.NewStore()
335		s.Publish(org, 0, []darksafe.Policy{
336			{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
337		})
338		s.Decide(org, darksafe.OrgRequest{
339			SubjectOrg: org, ResourceOrg: org,
340			Subject:  darksafe.Subject{ID: "u1"},
341			Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
342			Action:   "read",
343		})
344		s.Publish(org, 1, nil)
345		// The later decision uses a unique subject so its bytes are locatable and
346		// cannot be confused with the early record under review.
347		s.Decide(org, darksafe.OrgRequest{
348			SubjectOrg: org, ResourceOrg: org,
349			Subject:  darksafe.Subject{ID: "late-subject"},
350			Resource: darksafe.Resource{ID: "r9", Scope: "org/a"},
351			Action:   "read",
352		})
353		recs, cp, err := s.AuditExport(org, 0)
354		if err != nil {
355			t.Fatal(err)
356		}
357		good, err := darksafe.EncodeAuditArchive(org, recs, cp)
358		if err != nil {
359			t.Fatal(err)
360		}
361	
362		tampered := reframeArchive(t, good, func(payload []byte) {
363			idx := bytes.Index(payload, []byte("late-subject"))
364			if idx < 0 {
365				t.Fatal("later record subject not located in payload")
366			}
367			payload[idx] ^= 0x01 // same length; only the later record's content changes
368		})
369		path := filepath.Join(t.TempDir(), "late-damage.bin")
370		if err := os.WriteFile(path, tampered, 0o600); err != nil {
371			t.Fatal(err)
372		}
373	
374		code, out, errOut := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...)
375		if code != 1 {
376			t.Fatalf("later-record tamper exit = %d, want 1; %s", code, errOut)
377		}
378		if !strings.Contains(errOut, "invalid audit range") {
379			t.Fatalf("tampering a later record must fail chain validation, got %q", errOut)
380		}
381		if out != "" {
382			t.Fatalf("no partial output allowed, got %q", out)
383		}
384	}
385	
386	// TestReviewPreservesDistinctRawBytes ensures output quoting keeps a lone
387	// 0xFF, a lone 0xFE and a genuine U+FFFD in matched policy identifiers
388	// distinguishable rather than folding all invalid bytes onto one rune.
389	func TestReviewPreservesDistinctRawBytes(t *testing.T) {
390		rawIDArchive := func(t *testing.T, id string) (string, darksafe.Checkpoint) {
391			t.Helper()
392			const org = "raw org"
393			s := darksafe.NewStore()
394			s.Publish(org, 0, []darksafe.Policy{
395				{ID: id, Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
396			})
397			s.Decide(org, darksafe.OrgRequest{
398				SubjectOrg: org, ResourceOrg: org,
399				Subject:  darksafe.Subject{ID: "u1"},
400				Resource: darksafe.Resource{ID: "r", Scope: "org/a"},
401				Action:   "read",
402			})
403			recs, cp, err := s.AuditExport(org, 0)
404			if err != nil {
405				t.Fatal(err)
406			}
407			arc, err := darksafe.EncodeAuditArchive(org, recs, cp)
408			if err != nil {
409				t.Fatal(err)
410			}
411			p := filepath.Join(t.TempDir(), "raw.bin")
412			if err := os.WriteFile(p, arc, 0o600); err != nil {
413				t.Fatal(err)
414			}
415			return p, cp
416		}
417	
418		outputs := map[string]string{}
419		for name, id := range map[string]string{
420			"ff":   "p\xff",
421			"fe":   "p\xfe",
422			"uffd": "p�",
423		} {
424			path, cp := rawIDArchive(t, id)
425			code, out, errOut := runDispatch(t, reviewArgs(path, "raw org", 2, cp.EndSeq, cp.Fingerprint)...)
426			if code != 0 {
427				t.Fatalf("%s review failed: %s", name, errOut)
428			}
429			outputs[name] = out
430		}
431		if outputs["ff"] == outputs["fe"] || outputs["ff"] == outputs["uffd"] || outputs["fe"] == outputs["uffd"] {
432			t.Fatalf("distinct raw bytes collapsed:\nff:  %q\nfe:  %q\nuffd:%q",
433				outputs["ff"], outputs["fe"], outputs["uffd"])
434		}
435		if !strings.Contains(outputs["ff"], `"p\xff"`) {
436			t.Fatalf("0xFF must render as quoted \\xff:\n%s", outputs["ff"])
437		}
438		if !strings.Contains(outputs["fe"], `"p\xfe"`) {
439			t.Fatalf("0xFE must render as quoted \\xfe:\n%s", outputs["fe"])
440		}
441		if !strings.Contains(outputs["uffd"], `p�`) {
442			t.Fatalf("a real U+FFFD must render as itself, not an escape:\n%s", outputs["uffd"])
443		}
444	}
445	
446	// syntheticEnvelope mirrors the library's internal fingerprint envelope for
447	// the all-valid-UTF-8 case: record fingerprints are the SHA-256 of this JSON
448	// shape (see audit.go's hashEnvelope), and the genesis root is
449	// SHA-256("darksafe-audit-genesis\x00"+org). Field order and tags are
450	// load-bearing because the hash is order-sensitive; EncodeAuditArchive below
451	// independently re-verifies every fingerprint, so any drift fails the test
452	// loudly rather than silently testing the wrong thing.
453	type syntheticEnvelope struct {
454		Org             string                   `json:"org"`
455		Seq             int                      `json:"seq"`
456		Kind            string                   `json:"kind"`
457		Change          *darksafe.PolicyChange   `json:"change,omitempty"`
458		Decision        *darksafe.DecisionRecord `json:"decision,omitempty"`
459		PrevFingerprint string                   `json:"prev"`
460	}
461	
462	func genesisFingerprintHex(org string) string {
463		sum := sha256.Sum256([]byte("darksafe-audit-genesis\x00" + org))
464		return hex.EncodeToString(sum[:])
465	}
466	
467	func envelopeFingerprint(env syntheticEnvelope) string {
468		b, err := json.Marshal(env)
469		if err != nil {
470			panic(err)
471		}
472		sum := sha256.Sum256(b)
473		return hex.EncodeToString(sum[:])
474	}
475	
476	// TestReviewInconsistentButValidExitsZero proves the central exit-code rule:
477	// material that chains correctly but whose recorded decision contradicts the
478	// recorded policy is NOT archive damage. The command prints both decisions in
479	// full, marks the disagreement, and still exits 0.
480	func TestReviewInconsistentButValidExitsZero(t *testing.T) {
481		const org = "acme"
482		req := darksafe.OrgRequest{
483			SubjectOrg: org, ResourceOrg: org,
484			Subject:  darksafe.Subject{ID: "u1"},
485			Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
486			Action:   "read",
487		}
488		rec1 := darksafe.AuditRecord{
489			Org: org, Seq: 1, Kind: darksafe.AuditPolicyChange,
490			Change: &darksafe.PolicyChange{
491				Version: 1,
492				Policies: []darksafe.Policy{
493					{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
494				},
495			},
496			PrevFingerprint: genesisFingerprintHex(org),
497		}
498		rec1.Fingerprint = envelopeFingerprint(syntheticEnvelope{
499			Org: rec1.Org, Seq: rec1.Seq, Kind: rec1.Kind,
500			Change: rec1.Change, PrevFingerprint: rec1.PrevFingerprint,
501		})
502		// The recorded decision claims a deny the v1 policy cannot produce.
503		rec2 := darksafe.AuditRecord{
504			Org: org, Seq: 2, Kind: darksafe.AuditDecision,
505			Decision: &darksafe.DecisionRecord{
506				Request: req,
507				Decision: darksafe.Decision{
508					Allowed: false, Reason: "matched deny policy", Matched: []string{"p1"}, Version: 1,
509				},
510			},
511			PrevFingerprint: rec1.Fingerprint,
512		}
513		rec2.Fingerprint = envelopeFingerprint(syntheticEnvelope{
514			Org: rec2.Org, Seq: rec2.Seq, Kind: rec2.Kind,
515			Decision: rec2.Decision, PrevFingerprint: rec2.PrevFingerprint,
516		})
517		records := []darksafe.AuditRecord{rec1, rec2}
518		cp := darksafe.Checkpoint{Org: org, EndSeq: 2, Fingerprint: rec2.Fingerprint}
519	
520		arc, err := darksafe.EncodeAuditArchive(org, records, cp)
521		if err != nil {
522			t.Fatalf("synthetic chain must encode/verify: %v", err)
523		}
524		path := filepath.Join(t.TempDir(), "inconsistent.bin")
525		if err := os.WriteFile(path, arc, 0o600); err != nil {
526			t.Fatal(err)
527		}
528	
529		code, out, errOut := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...)
530		if code != 0 {
531			t.Fatalf("a legitimate-but-inconsistent review must exit 0, got %d: %s", code, errOut)
532		}
533		for _, want := range []string{
534			"target sequence: 2",
535			"original decision:",
536			"recomputed decision:",
537			"consistent: no",
538			// Original preserved verbatim.
539			`reason: "matched deny policy"`,
540			// Recomputed from the recorded request against v1: allow.
541			`reason: "matched allow policy"`,
542			"allowed: false",
543			"allowed: true",
544		} {
545			if !strings.Contains(out, want) {
546				t.Fatalf("inconsistent review output missing %q:\n%s", want, out)
547			}
548		}
549	}
550	
551	// TestReviewMissingHistoricalVersionExitsOne builds a chain that is
552	// internally consistent but whose decision names version 5 although no
553	// policy change record in the material ever published it. Decode succeeds,
554	// targeting succeeds, but the historical version cannot be obtained: a
555	// distinguishable failure, exit 1, never a silent substitution with a newer
556	// version.
557	func TestReviewMissingHistoricalVersionExitsOne(t *testing.T) {
558		const org = "acme"
559		rec := darksafe.AuditRecord{
560			Org: org, Seq: 1, Kind: darksafe.AuditDecision,
561			Decision: &darksafe.DecisionRecord{
562				Request: darksafe.OrgRequest{
563					SubjectOrg: org, ResourceOrg: org,
564					Subject:  darksafe.Subject{ID: "u1"},
565					Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
566					Action:   "read",
567				},
568				Decision: darksafe.Decision{
569					Allowed: false, Reason: "no matching allow policy", Matched: nil, Version: 5,
570				},
571			},
572			PrevFingerprint: genesisFingerprintHex(org),
573		}
574		rec.Fingerprint = envelopeFingerprint(syntheticEnvelope{
575			Org: rec.Org, Seq: rec.Seq, Kind: rec.Kind,
576			Decision: rec.Decision, PrevFingerprint: rec.PrevFingerprint,
577		})
578		records := []darksafe.AuditRecord{rec}
579		cp := darksafe.Checkpoint{Org: org, EndSeq: 1, Fingerprint: rec.Fingerprint}
580		arc, err := darksafe.EncodeAuditArchive(org, records, cp)
581		if err != nil {
582			t.Fatalf("chain must encode: %v", err)
583		}
584		path := filepath.Join(t.TempDir(), "missing-version.bin")
585		if err := os.WriteFile(path, arc, 0o600); err != nil {
586			t.Fatal(err)
587		}
588	
589		code, out, errOut := runDispatch(t, reviewArgs(path, org, 1, cp.EndSeq, cp.Fingerprint)...)
590		if code != 1 {
591			t.Fatalf("unavailable historical version must exit 1, got %d: %s", code, errOut)
592		}
593		if !strings.Contains(errOut, "version not found") {
594			t.Fatalf("failure must name the missing version distinctly, got %q", errOut)
595		}
596		if out != "" {
597			t.Fatalf("failure must print no partial decision, got %q", out)
598		}
599	}
600	
601	func TestReviewHelp(t *testing.T) {
602		for _, flag := range []string{"--help", "-h"} {
603			code, out, errOut := runDispatch(t, "review", flag)
604			if code != 0 || errOut != "" {
605				t.Fatalf("review %s: code=%d stderr=%q", flag, code, errOut)
606			}
607			for _, want := range []string{
608				"--archive", "--org", "--seq", "--end-seq", "--fingerprint",
609				"informational only", "Example:", "darksafe review",
610				"Exit codes",
611			} {
612				if !strings.Contains(out, want) {
613					t.Fatalf("review help missing %q:\n%s", want, out)
614				}
615			}
616		}
617	}
618	
619	// TestLegencyCommandsSurvive locks in the original CLI surface.
620	func TestLegacyCommandsSurvive(t *testing.T) {
621		if code, out, _ := runDispatch(t); code != 0 || !strings.Contains(out, "summary:") {
622			t.Fatalf("no-arg demo changed: code=%d out=%q", code, out)
623		}
624		if code, out, _ := runDispatch(t, "demo"); code != 0 || !strings.Contains(out, "summary:") {
625			t.Fatalf("demo changed: code=%d out=%q", code, out)
626		}
627		if code, out, _ := runDispatch(t, "version"); code != 0 || strings.TrimSpace(out) != "darksafe 0.1.0" {
628			t.Fatalf("version changed: code=%d out=%q", code, out)
629		}
630		if code, out, _ := runDispatch(t, "help"); code != 0 || !strings.Contains(out, "usage:") {
631			t.Fatalf("help changed: code=%d out=%q", code, out)
632		}
633		if code, _, errOut := runDispatch(t, "bogus"); code != 2 || errOut == "" {
634			t.Fatalf("unknown command exit = %d stderr=%q", code, errOut)
635		}
636	}
637	
638	// TestReviewIsReadOnlyOnFile ensures a successful review leaves the archive
639	// bytes untouched.
640	func TestReviewIsReadOnlyOnFile(t *testing.T) {
641		const org = "acme"
642		path, cp := fixtureChain(t, org)
643		before, err := os.ReadFile(path)
644		if err != nil {
645			t.Fatal(err)
646		}
647		if code, _, errOut := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...); code != 0 {
648			t.Fatalf("review: %d %s", code, errOut)
649		}
650		after, err := os.ReadFile(path)
651		if err != nil {
652			t.Fatal(err)
653		}
654		if !bytes.Equal(before, after) {
655			t.Fatal("review modified the archive file")
656		}
657	}
